data='"""Trainable IndoBERT last two layers with frozen-front/CLIP caches."""\nfrom pathlib import Path\nimport json,random\nimport numpy as np,torch\nfrom torch import nn\nfrom transformers import BertConfig\nfrom transformers.models.bert.modeling_bert import BertLayer\nTASKS=(\'task1_issue\',\'task2_domain_sumber\',\'task3_primary_entity_type\');TARGET=TASKS[1]\nCFG=dict(hidden=256,dropout=.3,visual_weight=2.,loss_weights=[1.,2.,2.],encoder_lr=2e-5,head_lr=3e-4,weight_decay=.01,batch=32,epoch_candidates=[0,2,4,8,12,24],seed=42)\ndef seed():random.seed(42);np.random.seed(42);torch.manual_seed(42)\ndef class_weights(y,n):\n    c=np.bincount(y,minlength=n).astype(np.float32)\n    return torch.tensor(np.where(c>0,len(y)/(np.maximum(c,1)*(c>0).sum()),0.),dtype=torch.float32)\nclass Head(nn.Module):\n    def __init__(self,nc):\n        super().__init__();self.shared=nn.Sequential(nn.Linear(2304,CFG[\'hidden\']),nn.ReLU(),nn.Dropout(CFG[\'dropout\']));self.heads=nn.ModuleDict({t:nn.Linear(CFG[\'hidden\'],nc[t]) for t in TASKS})\n    def forward(self,x):\n        h=self.shared(x);return {t:layer(h) for t,layer in self.heads.items()}\nclass TailMTL(nn.Module):\n    def __init__(self,nc,cache):\n        super().__init__();config=BertConfig.from_dict(json.loads((Path(cache)/\'bert_config.json\').read_text()));config._attn_implementation=\'sdpa\'\n        self.tail=nn.ModuleList([BertLayer(config),BertLayer(config)]);self.tail.load_state_dict(torch.load(Path(cache)/\'tail_initial.pt\',map_location=\'cpu\',weights_only=True));self.head=Head(nc)\n    def features(self,h,attention,pool_mask,visual):\n        am=(~attention.bool()[:,None,None,:]).to(h.dtype)*torch.finfo(h.dtype).min\n        for layer in self.tail:\n            h=layer(h,attention_mask=am)\n            if isinstance(h,tuple):h=h[0]\n        pm=pool_mask.to(h.dtype);text=(h*pm.unsqueeze(-1)).sum(dim=1)/pm.sum(dim=1,keepdim=True)\n        text=nn.functional.normalize(text.float(),p=2,dim=1)\n        return torch.cat([visual.float()*CFG[\'visual_weight\'],text],dim=1)\n    def forward(self,h,attention,pool_mask,visual):return self.head(self.features(h,attention,pool_mask,visual))\ndef warm_head(z,y,nc,tr):\n    seed();head=Head(nc);opt=torch.optim.AdamW(head.parameters(),lr=.001,weight_decay=.0001)\n    x=torch.tensor(np.hstack([z[\'visual\'][tr]*CFG[\'visual_weight\'],z[\'base_mean\'][tr]]));truth={t:torch.tensor(y[t][tr]) for t in TASKS};loss={t:nn.CrossEntropyLoss(weight=class_weights(y[t][tr],nc[t])) for t in TASKS}\n    head.train()\n    for _ in range(120):\n        opt.zero_grad();pred=head(x);l=sum(w*loss[t](pred[t],truth[t]) for t,w in zip(TASKS,CFG[\'loss_weights\']))/sum(CFG[\'loss_weights\']);l.backward();opt.step()\n    return {k:v.detach().clone() for k,v in head.state_dict().items()}\ndef batch_tensors(z,ix,device):\n    length=int(z[\'attention\'][ix].sum(axis=1).max())\n    return tuple(torch.tensor(z[k][ix,:length] if k in [\'h10\',\'attention\',\'pool_mask\'] else z[k][ix],device=device) for k in [\'h10\',\'attention\',\'pool_mask\',\'visual\'])\n\nCONFIGS=[dict(CFG,encoder_lr=lr,loss_weights=weights) for lr in [2e-6,2e-5,1e-4] for weights in [[1.,1.,1.],[1.,2.,2.]]]\n\ndef select_candidate(candidates):\n    return max([(ci,e) for ci in range(len(CONFIGS)) for e in CONFIGS[ci][\'epoch_candidates\']],key=lambda pair:candidates[pair[0]][\'epoch_scores\'][pair[1]])\n'
assert hashlib.sha256(data.encode()).hexdigest()=='1858ad58236e4e09bbd939fe24097c9cc3aa45476bfd608778d1895fb19860c0'
Path('/kaggle/working/tail_model.py').write_text(data)
data='"""Train-only duplication and predeclared inner-selection helpers."""\nimport hashlib\nimport json\nfrom collections import Counter\nfrom pathlib import Path\n\nimport numpy as np\n\nTASKS=(\'task1_issue\',\'task2_domain_sumber\',\'task3_primary_entity_type\')\n\n\ndef sha(path):\n    h=hashlib.sha256()\n    with Path(path).open(\'rb\') as handle:\n        for data in iter(lambda:handle.read(1024*1024),b\'\'):h.update(data)\n    return h.hexdigest()\n\n\ndef write(path,value):\n    Path(path).write_text(json.dumps(value,indent=2)+\'\\n\')\n\n\ndef duplicate_train(train, forbidden, factor):\n    train=np.asarray(train,dtype=np.int64)\n    assert factor in (1,2) and train.ndim==1 and len(train)>0\n    assert len(set(train.tolist()))==len(train), \'Split unique originals BEFORE duplication\'\n    assert not set(train.tolist()) & set(map(int,forbidden)), \'Held-out ID in training\'\n    expanded=np.tile(train,factor)\n    assert Counter(expanded.tolist())==Counter({int(i):factor for i in train})\n    return expanded\n\n\ndef select_epoch(traces,candidates):\n    assert len(traces)==2\n    scores={int(e):min(float(np.mean([trace[\'epochs\'][str(e)][t] for trace in traces])) for t in TASKS) for e in candidates}\n    # Iteration order implements earliest-epoch exact tie break.\n    chosen=max(candidates,key=lambda e:scores[int(e)])\n    return int(chosen),scores\n\n\ndef split_audit(ids,train,validation,test,factor):\n    a,b,c=map(lambda values:set(map(int,values)),(train,validation,test))\n    assert not a&b and not a&c and not b&c\n    expanded=duplicate_train(train,b|c,factor)\n    return dict(train_ids=[str(ids[i]) for i in train],validation_ids=[str(ids[i]) for i in validation],\n                test_ids=[str(ids[i]) for i in test],unique_train_samples=len(train),\n                train_exposures_per_epoch=len(expanded),factor=factor,\n                multiplicity={str(ids[i]):factor for i in train})\n'
